function Find_Min(lst) {
  if (lst.length === 0) return [];
  if (lst.length === 1) return lst;

  let minSum = Infinity;
  let currentSum = 0;
  let start = 0;
  let end = 0;
  let tempStart = 0;

  for (let i = 0; i < lst.length; i++) {
    currentSum += lst[i];
    if (currentSum < minSum) {
      minSum = currentSum;
      start = tempStart;
      end = i;
    }
