function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(N).fill(null).map(() => new Array(N).fill(false));
    const pq = [];

    function dfs(x, y, path) {
        if (path.length === k) {
            pq.push([...path]);
            return;
        }
        visited[x][y] = true;
        for (const [dx, dy] of directions) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, path.concat(grid[nx][ny]));
            }
        }
        visited[x][y] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]]);
        }
    }

    pq.sort((a, b) => {
        for (let i = 0; i < a.length; i++) {
            if (a[i] !== b[i]) return a[i] - b[i];
        }
        return 0;
    });

    return pq[0];
}

function minPath(grid, k) {
  const n = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let result = [];

  function dfs(x, y, path) {
    if (path.length === k) {
      if (result.length === 0 || path < result) {
        result = path;
      }
      return;
    }
    for (let [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
        dfs(nx, ny, path.concat(grid[nx][ny]));
      }
    }
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dfs(i, j, [grid[i][j]]);
    }
  }

  return result;
}

