        let sum = 1;
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let a = 2; a < limit; a++) {
        let b = sumOfDivisors(a);
        if (a !== b && sumOfDivisors(b) === a) {
            sum += a;
        }
    }
    return sum;
}

