    for (let gap = Math.floor(n / 2); gap > 0; gap = Math.floor(gap / 2)) {
        for (let i = gap; i < n; i++) {
            let temp = my_list[i];
            let j;
            for (j = i; j >= gap && my_list[j - gap] > temp; j -= gap) {
                my_list[j] = my_list[j - gap];
            }
            my_list[j] = temp;
        }
    }
    return my_list;
}

