function search(lst) {
  const frequencyMap = lst.reduce((acc, num) => {
    acc[num] = (acc[num] || 0) + 1;
    return acc;
  }, {});

  let result = -1;
  for (const num in frequencyMap) {
    const frequency = frequencyMap[num];
    if (num <= frequency && num > result) {
      result = num;
    }
  }

  return result;
}

function max_subarray_product(arr) {
    if (arr.length === 0) return 0;

    let maxProduct = arr[0];
    let minProduct = arr[0];
    let result = arr[0];

    for (let i = 1; i < arr.length; i++) {
        let tempMax = Math.max(arr[i], maxProduct * arr[i], minProduct * arr[i]);
        minProduct = Math.min(arr[i], maxProduct * arr[i], minProduct * arr[i]);
        maxProduct = tempMax;

        result = Math.max(result, maxProduct);
    }

    return result;
}

