function get_max_sum(n) {
    let memo = {};
    function helper(x) {
        if (x <= 1) return x;
        if (memo[x] !== undefined) return memo[x];
        memo[x] = Math.max(helper(Math.floor(x / 2)) + helper(Math.floor(x / 3)) + helper(Math.floor(x / 4)) + helper(Math.floor(x / 5)), x);
        return memo[x];
    }
    return helper(n);
}

