function get_median(arr1, arr2, n){
    let i = 0; 
    let j = 0; 
    let m1 = -1, m2 = -1; 

    for (let count = 0; count <= n; count++) { 
        m2 = m1; 
        if (i == n) { 
            m1 = arr2[0]; 
            break; 
        } 
        else if (j == n) { 
            m1 = arr1[0]; 
            break; 
        } 
        else if (arr1[i] <= arr2[j]) { 
            m1 = arr1[i]; 
            i++; 
        } 
        else { 
            m1 = arr2[j]; 
            j++; 
        } 
    } 
    return (m1 + m2)/2; 
}

