function reverse_Array_Upto_K(input, k) {
    // Extract the part of the array that needs to be reversed
    let partToReverse = input.slice(0, k + 1);
    // Reverse the extracted part
    partToReverse.reverse();
    // Concatenate the reversed part with the rest of the array
    return partToReverse.concat(input.slice(k + 1));
}

function reverse_Array_Upto_K(input, k) {
    if (k >= input.length) {
        return input.reverse();
    }
    let reversedPart = input.slice(0, k + 1).reverse();
    let remainingPart = input.slice(k + 1);
    return [...reversedPart, ...remainingPart];
}

