function find_closest_elements(numbers){
    numbers.sort((a, b) => a - b);
    let minDiff = Infinity;
    let closestPair = [];

    for (let i = 0; i < numbers.length - 1; i++) {
        let diff = numbers[i + 1] - numbers[i];
        if (diff < minDiff) {
            minDiff = diff;
            closestPair = [numbers[i], numbers[i + 1]];
        }
    }

    return closestPair;
}
